import {createEventPages} from '/event-pages.js?v=gaac-resource-whitepaper-20261105';
(() => {
  'use strict';
  const app = document.querySelector('#app');
  const params = new URLSearchParams(location.search);
  const stored = key => {try{return localStorage.getItem(key)}catch{return null}};
  const persist = (key,value) => {try{localStorage.setItem(key,value)}catch{}};
  const themes = ['cobalt','acid','iris'];
  let theme = params.get('design') || 'iris';
  if(!themes.includes(theme)) theme='iris';
  const typefaces=['unbounded','michroma','syncopate'];
  let typeface=params.get('type')||'michroma';
  if(!typefaces.includes(typeface))typeface='michroma';
  const cnFonts=['chill','system'];
  let cnFont=params.get('cn')||'chill';
  if(!cnFonts.includes(cnFont))cnFont='chill';
  let lang = params.get('lang') || 'zh';
  if(!['en','zh'].includes(lang))lang='zh';
  let disposeHero, disposeArt, disposeGlass, lastGuideStep, renderVersion=0;
  const t=(en,zh)=>lang==='zh'?zh:en;
  const arrow='<span class="arrow" aria-hidden="true">↗</span>';
  const right='<span class="arrow" aria-hidden="true">→</span>';
  const cleanURL=(u,design=theme)=>{u.searchParams.delete('v');for(const [key,value,fallback] of [['design',design,'iris'],['lang',lang,'zh'],['type',typeface,'michroma'],['cn',cnFont,'chill']]){if(value===fallback)u.searchParams.delete(key);else u.searchParams.set(key,value);}return u;};
  const href=(path,design=theme)=>{const u=cleanURL(new URL(path,location.origin),design);return u.pathname+u.search+u.hash;};
  history.replaceState(history.state,'',cleanURL(new URL(location.href)));
  const link=(path,label,cls='text-link',design=theme)=>`<a class="${cls}" href="${href(path,design)}">${label}${arrow}</a>`;
  const eyebrow=(label,dot=false)=>`<div class="eyebrow">${dot?'<span class="dot"></span>':''}${label}</div>`;
  const sectionLabel=(n,label)=>`<div class="section-label mono"><span>${n}</span><span>${label}</span></div>`;
  const notice=text=>`<div class="notice">${text}</div>`;
  const rows=items=>items.map((r,i)=>`<div class="info-row"><span class="micro">${String(i+1).padStart(2,'0')}</span><h3>${r[0]}</h3><p>${r[1]}</p></div>`).join('');
  const table=(headers,body)=>`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${body.map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  const faq=items=>items.map(r=>`<details class="faq"><summary>${r[0]}</summary><p>${r[1]}</p></details>`).join('');
  const article=(id,title,content)=>`<section class="article-section" id="${id}"><h2>${title}</h2>${content}</section>`;
  const sidebar=items=>`<aside class="sub-sidebar"><div class="micro">${t('On this page','本页内容')}</div>${items.map(r=>`<a href="#${r[0]}">${r[1]}</a>`).join('')}</aside>`;
  const pageHero=(_label,title,desc,cta='')=>`<div class="wrap"><section class="page-hero"><div><h1>${title}</h1></div><div><p>${desc}</p>${cta}</div></section></div>`;
  const subLayout=(items,content)=>`<div class="wrap sub-layout">${sidebar(items)}<div>${content}</div></div>`;
  const oaicHref=()=>`https://www.oaic.ai/?lang=${lang}`;
  const oaicMark=()=>theme==='acid'?'/assets/oaic-logo-dark.png':'/assets/oaic-logo-light.png';
  function header(page){return `<div class="wrap"><header class="site-header"><div class="brand"><a class="gaac-home" href="${href('/')}" aria-label="Grand Agentic AI Challenge — ${t('Home','赛事首页')}"><img src="/assets/gaac-logo.png" alt="GAAC — Grand Agentic AI Challenge" width="156" height="52"></a><div class="brand-partners"><a class="brand-by" href="${oaicHref()}" target="_blank" rel="noopener" aria-label="${t('OAIC — Official website','OAIC — 官网')}"><img class="oaic-mark" src="${oaicMark()}" alt="OAIC — 开放智能体产业联盟" width="92" height="42"></a><a class="gosim-brand" href="https://gosim.org/" target="_blank" rel="noopener" aria-label="GOSIM — 官网"><img src="/assets/gosim-logo.svg" alt="GOSIM" width="85" height="24"></a></div></div><nav class="main-nav" id="main-nav" aria-label="${t('Main navigation','主导航')}"><a class="nav-link ${page==='challenge'?'active':''}" href="${page==='home'?'#participant-guide':href('/#participant-guide')}">${t('Participant guide','参赛指南')}</a><a class="nav-link ${page==='resources'?'active':''}" href="${href('/resources/')}">${t('Format & scoring','赛制与评分')}</a><a class="nav-link nav-registration-mobile" href="${href('/teams/')}">${t('Registration','报名参赛')}</a><details class="nav-dropdown"><summary class="nav-link">${t('Cooperate','合作参与')} <span>⌄</span></summary><div class="dropdown-panel">${[['partners',t('Sponsors & partners','赞助与资源伙伴')],['enterprise',t('Enterprise users','企业用户与场景')],['research',t('Research & education','高校与研究机构')],['ecosystem',t('Post-event collaboration','赛后产业合作')]].map(r=>`<a href="${href('/'+r[0]+'/')}">${r[1]}${arrow}</a>`).join('')}</div></details></nav><div class="header-actions"><button class="language" data-action="language" aria-label="${t('Switch to Chinese','切换为英文')}">${t('中文','EN')}</button>${link('/teams/',t('Registration','报名参赛'),'button small dark')}<button class="mobile-toggle" data-action="menu" aria-expanded="false" aria-controls="main-nav" aria-label="${t('Open navigation','打开导航')}">☰</button></div></header></div>`;}
  function footer(page){return `<footer class="site-footer"><div class="wrap"><div class="event-footer-identity">Grand Agentic AI Challenge<span>${t('A real-application challenge for full-stack agentic engineering and industry collaboration.','智能体大奖赛 · 赛事招募与产业合作')}</span></div><div class="footer-top"><a class="footer-brand" href="${oaicHref()}" target="_blank" rel="noopener" aria-label="${t('OAIC — Open Agentic Industry Consortium','OAIC — 开放智能体产业联盟')}"><img class="oaic-mark" src="${oaicMark()}" alt="OAIC — Open Agentic Industry Consortium" width="190"></a><div class="footer-nav"><a href="${page==='home'?'#participant-guide':href('/#participant-guide')}">${t('Participant guide','参赛指南')}</a><a href="${href('/teams/')}">${t('Registration & teams','报名与组队')}</a><a href="${href('/partners/')}">${t('Sponsorship','赞助合作')}</a><a href="${href('/resources/')}">${t('Rules & assessment','考试与评估')}</a><a href="${href('/ecosystem/')}">${t('Industry collaboration','产业合作')}</a><a href="https://gaac.gosim.org/" target="_blank" rel="noopener">gaac.gosim.org ↗</a></div></div><div class="footer-bottom"><p>${t('Registration, team formation, sponsorship and enterprise cooperation channels are announced through the event website. Dates, selections, platform windows and detailed technical rules are published by the organizing committee.','报名、组队、赞助与企业合作入口请关注赛事官网。时间、入选安排、上机日历和详细技术规则，由组委会统一公告。')}</p><span>© ${new Date().getFullYear()} GAAC · ${t('An OAIC initiative','OAIC 产业生态共建')}</span></div></div></footer>`;}
  function dock(){return `<aside class="design-dock" aria-label="${t('Compare website design directions','对比网站设计方向')}"><span class="dock-label">${t('Design','设计')} 0${themes.indexOf(theme)+1}</span>${themes.map((v,i)=>`<button class="theme-choice" data-theme="${v}" data-action="theme" aria-label="${['Electric Cobalt','Acid Signal','Sky Editorial'][i]}" aria-pressed="${v===theme}" title="${['Electric Cobalt','Acid Signal','Sky Editorial'][i]}">${v}</button>`).join('')}<span class="dock-divider"></span><a class="dock-compare" href="${href('/directions/')}">${t('Compare & film ideas','对比设计与视频灵感')} ↗</a></aside>`;}
  function taskArt(type){
    const start=`<svg viewBox="0 0 360 200" aria-hidden="true"><defs><filter id="sh-${type}" x="-50%" y="-50%" width="200%" height="200%"><feDropShadow dx="0" dy="8" stdDeviation="8" flood-opacity=".08"/></filter></defs>`;
    if(type===0)return start+`<g transform="translate(84 35) rotate(-8 95 65)" filter="url(#sh-0)"><rect width="190" height="125" fill="var(--soft)" stroke="currentColor" stroke-opacity=".25"/><rect x="16" y="18" width="70" height="5" fill="currentColor"/><rect x="16" y="31" width="43" height="3" fill="currentColor" opacity=".35"/><path d="M25 98 57 60 87 98M113 98V65H130V98M140 98V49H157V98" fill="none" stroke="currentColor" stroke-width="6"/><path d="M176 12h7v7M7 106v7h7" fill="none" stroke="currentColor"/></g><g transform="translate(115 65) rotate(5 95 65)" filter="url(#sh-0)"><rect width="175" height="105" fill="var(--paper)" stroke="currentColor" stroke-opacity=".4"/><text x="14" y="20" fill="currentColor" font-family="Arial" font-size="8" letter-spacing="1">OPEN INTELLIGENCE</text><path d="M14 38h73M14 45h51" stroke="currentColor" stroke-width="3" opacity=".3"/><path d="M113 80 136 42 159 80M130 74h13" fill="none" stroke="currentColor" stroke-width="6"/><rect x="14" y="68" width="66" height="20" fill="var(--soft)"/></g></svg>`;
    if(type===1)return start+`<g transform="translate(70 25)" filter="url(#sh-1)"><rect width="220" height="150" fill="var(--paper)" stroke="currentColor" stroke-opacity=".3"/><path d="M0 25h220M34 0v150" stroke="currentColor" stroke-opacity=".2"/><text x="11" y="17" fill="currentColor" font-family="monospace" font-size="8">ƒx</text><g stroke="currentColor" stroke-opacity=".1"><path d="M34 50h186M34 75h186M34 100h186M34 125h186M80 25v125M126 25v125M172 25v125"/></g><path d="M55 111 87 91 120 99 151 67 191 48" stroke="currentColor" stroke-width="3" fill="none"/><path d="M55 111 87 91 120 99 151 67 191 48V133H55Z" fill="currentColor" opacity=".08"/><g fill="currentColor"><circle cx="55" cy="111" r="4"/><circle cx="87" cy="91" r="4"/><circle cx="120" cy="99" r="4"/><circle cx="151" cy="67" r="4"/><circle cx="191" cy="48" r="4"/></g><rect x="150" y="18" width="57" height="20" fill="var(--soft)"/><text x="158" y="31" fill="currentColor" font-family="monospace" font-size="8">TRACEABLE</text></g></svg>`;
    return start+`<g stroke="currentColor" fill="none" stroke-opacity=".45"><path d="M91 58 175 105 269 50M175 105 268 143M175 105 102 154"/><circle cx="175" cy="105" r="31" stroke-opacity=".16"/><circle cx="175" cy="105" r="46" stroke-opacity=".1"/></g><g fill="var(--paper)" stroke="currentColor" stroke-opacity=".4"><rect x="60" y="25" width="64" height="76" transform="rotate(-10 92 63)"/><rect x="241" y="20" width="53" height="65" transform="rotate(9 267 52)"/><rect x="245" y="117" width="53" height="56" transform="rotate(-5 270 145)"/><rect x="78" y="135" width="50" height="40" transform="rotate(5 103 155)"/></g><g stroke="currentColor" stroke-width="2" opacity=".35"><path d="M76 45h30M75 52h28M74 60h23M252 39h26M253 46h22M256 135h28M256 142h22M88 148h27M89 155h21"/></g><circle cx="175" cy="105" r="17" fill="currentColor"/><path d="m168 105 5 5 9-10" fill="none" stroke="var(--paper)" stroke-width="2"/></svg>`;
  }
  const prompts=[
    'A seamless 10-second architectural motion loop for an open-source AI engineering initiative. On a pale cool-white background, two sculptural electric-cobalt blue tubular triangular forms slowly approach, rotate, and interlock while retaining a small visible opening. Their silhouette subtly recalls two angular A peaks and broken circular strokes. Physically based glossy ceramic material, precise beveled edges, soft studio daylight, restrained shadows, premium design exhibition aesthetic. Slow deliberate movement, fixed camera, no cuts, no flashy particles. Sculpture placed in the right 55 percent, generous clean negative space on the left for web typography. Palette strictly cobalt #244BFF, cool white #F6F7F5, pale blue #E9EDFF, ink #171919. No orange, no warm lighting, no text, no lettering, no logos, no humans, no robots, no interface. First and last frames match. 16:9, 24 fps, 4K master.',
    'A seamless 8-second macro engineering film for an open-source full-stack agent challenge. Near-black graphite space. Three precise streams of acid-lime light travel across a minimalist layered architectural structure, meet at an open triangular frame, then resolve into three small clean geometric artifacts: a presentation sheet, a chart plane, and a research-page stack, represented only by abstract geometry without readable content. Camera drifts extremely slowly along a single smooth path. Industrial precision, dark anodized metal, luminous lime edges, sparse ice-cyan reflections, crisp spatial depth. Keep the left 50 percent quiet and almost black for typography. Palette #11150F, #D8FF3E, #8AE6FF. No orange, no purple gradients, no sparks, no circuit-board clichés, no humanoid robots, no text, no lettering, no logos. Understated continuous movement, no cuts. Return to the exact starting composition. 16:9, 24 fps, 4K master.',
    'A seamless 12-second editorial sculpture loop about collective intelligence. In a porcelain-white gallery, translucent sky-blue architectural ribbons and thin paper-like planes drift gently into a single open double-peak structure, leaving room between pieces so every contribution remains visible. The sculpture opens and relaxes back to the initial arrangement. Elegant tactile materials: frosted sky-blue glass, satin ice-blue ceramic, porcelain-white paper. Large soft shadows, diffuse neutral daylight, sculptural art direction, luxury cultural-publication aesthetic. Fixed camera, medium-wide framing, restrained shallow depth of field. Keep the subject in the right 55 percent and leave the left half empty for live website copy. Palette sky blue #8AE6FF, porcelain #F6FAFA, deep ink #102C3A, pale ice #E4F5FA. Broad, low architectural proportions echo an extended geometric wordmark. No purple, no orange, no gold, no pink lighting, no text or generated typography, no logos, no humans. No fast cuts or explosions. First frame and final frame identical. 16:9, 24 fps, 4K master.'
  ];
  const concepts=()=>[
    {id:'cobalt',name:'Electric Cobalt',tag:t('Original exploration','原始探索'),desc:t('Confident, architectural, and exceptionally clear. Cool white, oversized sans-serif type, and sculptural cobalt make the initiative feel serious without feeling institutional.','自信、建筑感、清晰。冷白留白、大字号无衬线字体与钴蓝雕塑，让项目既专业，也有鲜明个性。'),colors:['#244BFF','#F6F7F5','#171919','#E9EDFF'],best:t('The original cobalt exploration, retained for comparison.','保留最初的钴蓝色探索，便于对比。'),ref:'https://www.pentagram.com',refName:'Pentagram',refWhy:t('graphic clarity & art direction','图形秩序与艺术指导'),film:t('Open assembly','开放的组合'),story:t('Separate open forms become one structure. A visual metaphor for existing open-source components working together without becoming a closed platform.','开放的独立形体形成共同结构，象征已有开源组件协同工作，同时保留开放与可替换空间。'),duration:'10 s'},
    {id:'acid',name:'Acid Signal',tag:t('Most expressive','最有冲击力'),desc:t('A precise, after-dark engineering language. Near-black surfaces and sharp lime make a bold statement, with monospaced details that feel at home with systems builders.','精密的深色工程语言。近黑底色与明亮青柠形成强烈对比，等宽细节呼应系统开发者的世界。'),colors:['#D8FF3E','#11150F','#F0F3E9','#8AE6FF'],best:t('Best for an elite engineering challenge with a strong event identity.','适合强调精英工程挑战与鲜明赛事身份。'),ref:'https://linear.app',refName:'Linear',refWhy:t('precision, hierarchy & motion restraint','精确层级与克制动效'),film:t('From signal to substance','从信号到交付'),story:t('Three streams converge through a system and emerge as a presentation, a chart, and a report. It tells the full-stack story through tangible outputs.','三条信号穿过系统，形成演示稿、图表与研究报告，用具体工件讲清全栈协同的意义。'),duration:'8 s'},
    {id:'iris',name:'Sky Editorial',tag:t('Selected direction','已选方向'),desc:t('The third direction, refined around sky blue #8AE6FF. Naturally wide geometric type echoes the GAAC mark; deep ink, porcelain white, tactile forms, and generous space retain the editorial elegance.','以第三版为基础，用天蓝色 #8AE6FF、深墨蓝与瓷白重新搭配。更宽扁的几何字体呼应 GAAC 标志，保留拱形构图、材质感形体和充足留白。'),colors:['#8AE6FF','#F6FAFA','#102C3A','#E4F5FA'],best:t('The chosen direction: an airy, elegant identity with a wider, lower typographic rhythm.','当前主方向：轻盈优雅，以更宽、更低的字体比例连接 GAAC 的品牌形态。'),ref:'https://www.cosmos.so',refName:'Cosmos',refWhy:t('editorial space & visual curation','编辑式留白与视觉策展'),film:t('Collective form','共同成形'),story:t('Sky-blue glass and pale ceramic find a shared open architecture. A calm expression of research, industry, open source, and education contributing to one ambition.','天蓝色玻璃与浅色陶瓷共同构成开放建筑，以平静、通透的方式表达研究、产业、开源与教育的共同投入。'),duration:'12 s'}
  ];
  function directions(){return `<div class="wrap design-page"><section class="design-intro">${eyebrow(t('GAAC / A VISUAL DIRECTION TO BUILD ON','GAAC / 从视觉方向开始'),true)}<h1>${t('Three perspectives.<br>One open ambition.','三种视觉表达。<br>同一个开放愿景。')}</h1><p>${t('Compare three complete directions using the same content and page structure. The supplied GAAC mark remains the anchor: open strokes, angular peaks, and forward movement. Every palette excludes orange.','三种设计使用相同的信息架构与内容，便于直接比较。保留 GAAC 标志，以开放线条、几何山峰与向前的动势为灵感。所有配色均不含橙色。')}</p></section><section class="direction-overview" id="compare"><div class="overview-heading"><span class="micro">${t("THREE LIVE DESIGN DIRECTIONS","三种可体验的设计方向")}</span><a href="#films" class="text-link">${t("Hero film ideas","首屏视频灵感")} ${arrow}</a></div><div class="direction-tiles">${concepts().map((c,i)=>`<a class="direction-tile" href="${href("/",c.id)}"><img src="/assets/design-${c.id}.png?v=gaac-minimal-20261104a" alt="${c.name} ${t("homepage preview","首页预览")}"><div class="tile-heading"><span class="micro">0${i+1}</span><h2>${c.name}</h2>${arrow}</div><div class="tile-colors">${c.colors.map(v=>`<span><i style="background:${v}"></i>${v}</span>`).join("")}</div></a>`).join("")}</div></section>${concepts().map((c,i)=>`<section class="design-concept" id="${c.id}"><a class="design-preview" href="${href('/',c.id)}"><span class="preview-fallback" style="background:${c.colors[1]};color:${c.colors[0]}">${c.name}</span><img src="/assets/design-${c.id}.png?v=gaac-minimal-20261104a" alt="${c.name} — ${t('actual homepage screenshot','实际首页截图')}" loading="lazy" onerror="this.remove()"><span class="image-caption">${t('Actual website preview · click to explore','实际网站预览 · 点击探索')} ↗</span></a><div><div class="concept-title"><div><span class="micro">DIRECTION 0${i+1}</span><h2>${c.name}</h2></div><span class="recommend">${c.tag}</span></div><p class="concept-desc">${c.desc}</p><div class="swatches" aria-label="${c.name} ${t('color palette','配色')}">${c.colors.map(color=>`<div class="swatch"><div class="swatch-color" style="background:${color}"></div><div class="swatch-label">${color}</div></div>`).join('')}</div><p class="concept-meta"><b>${t('Best for:','适合：')}</b> ${c.best}<br><b>${t('Reference:','参考：')}</b> <a href="${c.ref}" target="_blank" rel="noopener">${c.refName} ↗</a> · ${c.refWhy}</p>${link('/',t('Explore this direction','探索这一方向'),'button',c.id)}<a class="reference-link" href="${c.ref}" target="_blank" rel="noopener">${t('View reference','查看参考')} ↗</a></div></section>`).join('')}<section class="section" id="films">${sectionLabel('04',t('HERO FILM CONCEPTS','首屏视频概念'))}<div class="section-header"><h2>${t('Make the idea move.','让理念，动起来。')}</h2><p class="section-intro">${t('These film briefs are available for future production. No AI videos have been generated.','以下保留三种可供后续制作的 AI 视频创意，尚未生成成片。')}</p></div>${concepts().map((c,i)=>`<article class="video-card"><div><span class="micro">0${i+1} / ${c.name} / ${c.duration} LOOP</span><h3>${c.film}</h3><p>${c.story}</p></div><div class="prompt-box"><p>${prompts[i]}</p><button data-action="copy-prompt" data-prompt="${i}">${t('Copy generation prompt','复制生成提示词')} ${arrow}</button></div></article>`).join('')}${notice(t('Production brief: generate a 16:9 4K master, then export a muted, seamless 1080p WebM with MP4 fallback. Keep website text outside the film. Aim for a light mobile asset (about 3–6 MB), provide a poster image and a visible pause control, and use the poster for reduced-motion or data-saving preferences. Crop the right-hand composition for mobile. Exact output size depends on duration and visual complexity.','制作建议：生成 16:9、4K 母版，压缩为静音循环 1080p WebM，附 MP4 回退。文字由网页渲染。移动端建议控制在约 3—6 MB，提供静态封面与暂停按钮，并尊重减少动态效果及节流偏好。移动端裁切右侧主体，文件体积依时长与复杂度调整。'))}</section><section class="section pathways">${sectionLabel('05',t('A CLEARER INFORMATION ARCHITECTURE','更清晰的信息架构'))}<h2>${t('The right detail.<br>On the right page.','让每种信息，<br>找到合适的位置。')}</h2><div class="sitemap">${[['/',t('Home','首页'),t('The proposition, three tasks, and paths to participate','项目主张、三类应用与参与入口')],['/challenge/',t('The challenge','挑战赛'),t('Format, applications, platform, and key questions','赛制、应用、平台与常见问题')],['/ecosystem/',t('The ecosystem','开放生态'),t('Testbed, reusable outputs, capabilities, and 90-day plan','Testbed、共同成果、能力与 90 天计划')],['/partners/',t('Sponsors & partners','赞助伙伴'),t('Contribution types, value, and milestone reporting','合作方式、价值与里程碑报告')],['/teams/',t('Teams & builders','参赛团队'),t('Team profile, journey, deliverables, and opportunities','团队画像、路径、交付与后续机会')],['/enterprise/',t('Enterprise adoption','企业采用'),t('Trial, training, deployment, pilot, and acceptance','试用、培训、部署、试点与验收')],['/research/',t('Research & education','高校研究'),t('Research questions, courses, and collaboration units','研究问题、课程与最小共建单元')],['/resources/',t('Rules & assessment','考试与评估'),t('Current event source, examination, scoring tracks and review principles','当前赛事原文、考试方向、双轨评分与评审原则')],['/involve/',t('Get involved','参与共建'),t('Audience paths and a local collaboration-brief builder','分角色入口与本地共建提议生成')]].map(v=>`<a href="${href(v[0])}"><div>${v[1]}<small>${v[2]}</small></div>${arrow}</a>`).join('')}</div></section></div>`;}
  function render(){
    const version=++renderVersion;
    if(disposeHero){disposeHero();disposeHero=null;}
    if(disposeArt){disposeArt();disposeArt=null;}
    if(disposeGlass){disposeGlass();disposeGlass=null;}
    const page=location.pathname.replace(/^\/+|\/+$/g,'').replace(/\/?index\.html$/,'')||'home';
    const pages={...createEventPages({t,href,link,arrow,right,eyebrow,sectionLabel,notice,rows,table,faq,article,pageHero,subLayout,taskArt}),directions};
    document.documentElement.dataset.theme=theme;
    document.documentElement.dataset.type=typeface;
    document.documentElement.dataset.cn=cnFont;
    document.documentElement.lang=lang==='zh'?'zh-CN':'en';
    document.body.className=theme+' '+page;
    document.querySelector('meta[name="theme-color"]').content=getComputedStyle(document.documentElement).getPropertyValue('--bg').trim();
    const names={home:t('Grand Agentic AI Challenge','智能体大奖赛'),challenge:t('Competition overview','赛事介绍'),ecosystem:t('Post-event industry collaboration','赛后产业合作'),partners:t('Sponsors & technology partners','赞助与技术资源伙伴'),teams:t('Registration & team formation','报名与自由组队'),enterprise:t('Enterprise scenarios & projects','企业场景与项目合作'),research:t('Research & education','高校研究与课程'),resources:t('Examination & assessment','考试内容与评估标准'),involve:t('Registration & cooperation','报名与参与方式'),directions:t('Visual directions & films','视觉方案与视频创意')};
    document.title=page==='home'?t('Grand Agentic AI Challenge — Competition & industry collaboration','Grand Agentic AI Challenge｜智能体大奖赛'):`GAAC ${t('Grand Agentic AI Challenge','智能体大奖赛')} — ${names[page]||'Page not found'}`;
    app.innerHTML=header(page)+`<main id="main">${pages[page]?pages[page]():`<div class="wrap not-found"><p class="eyebrow">404</p><h1>${t('An open question.','尚未找到这一页。')}</h1><p>${t('This page does not exist. Let’s get you back to the challenge.','这一页不存在，返回首页继续探索。')}</p>${link('/',t('Back to home','回到首页'),'button')}</div>`}</main>`+footer(page)+((page==='directions'||params.get('review')==='1')?dock():'');
    persist('gaac-design-v2',theme);persist('gaac-language-v2',lang);persist('gaac-typeface',typeface);persist('gaac-cn-font',cnFont);
    if(page==='home')import('/assets/liquid-guide.js?v=gaac-minimal-20261104a').then(({mountLiquidGuide})=>{if(version!==renderVersion)return;disposeGlass=mountLiquidGuide(document.querySelector('#liquid-guide'),{lang,initialId:lastGuideStep,onSelect:id=>{lastGuideStep=id;}});}).catch(error=>console.error('Liquid guide could not load',error));
    if(page==='home')import('/assets/hero-world.js?v=gaac-page-shadow-20261105').then(({mountHero})=>{if(version!==renderVersion)return;disposeHero=mountHero(document.querySelector('[data-hero-world]'),{lang});}).catch(error=>{if(version!==renderVersion)return;console.warn('GAAC Hero: static cover in use.',error);document.querySelector('[data-hero-world]')?.setAttribute('data-state','fallback');});
    if(page==='home'&&document.querySelector('#sculpture'))import('/art.js?v=gaac-minimal-20261104a').then(({createSculpture})=>{if(version!==renderVersion)return;disposeArt=createSculpture(document.querySelector('#sculpture'),theme,document.querySelector('.motion-toggle'));}).catch(()=>{document.querySelector('.motion-toggle')?.remove();});
    if(page==='involve'){
      const role=new URLSearchParams(location.search).get('role');
      if(role&&['partner','team','enterprise','research'].includes(role))document.querySelector('#role').value=role;
      document.querySelector('#brief-form').addEventListener('submit',makeBrief);
    }
    if(location.hash){requestAnimationFrame(()=>{let id;try{id=decodeURIComponent(location.hash.slice(1))}catch{return}let target=document.getElementById(id);if(page==='home'&&['tasks','eligibility','registration','schedule','scoring','after'].includes(id))target=document.getElementById('participant-guide');target?.scrollIntoView({block:'start',behavior:'instant'});});}
  }
  function setState(){history.replaceState({},'',cleanURL(new URL(location.href)));render();}
  function toast(message){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.role='status';el.textContent=message;document.body.appendChild(el);setTimeout(()=>el.remove(),3000);}
  async function copy(text){try{await navigator.clipboard.writeText(text);toast(t('Copied to clipboard','已复制到剪贴板'));return true}catch{toast(t('Clipboard unavailable. Select and copy the text.','剪贴板暂不可用，请选择文字复制。'));return false}}
  function download(text,name){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  let brief='';
  function makeBrief(e){e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const roleField=form.elements.namedItem('role');const role=roleField.options[roleField.selectedIndex].text;brief=`GAAC / OAIC — ${t('COLLABORATION BRIEF','共建提议')}\n\n${t('Participation path','参与身份')}: ${role}\n\n${t('Contribution / problem','贡献 / 问题')}:\n${form.elements.namedItem('contribution').value.trim()}\n\n${t('First deliverable / milestone','首项交付 / 里程碑')}:\n${form.elements.namedItem('milestone').value.trim()}\n\n${t('To agree together: owner, scope, resources, acceptance, data permissions, maintenance, and official contact.','待共同确认：负责人、范围、资源、验收、数据授权、维护与正式联络方式。')}\n\n${t('Prepared locally. Not a registration or an accepted agreement. Event information: https://gaac.gosim.org/','本地生成，不构成报名或合作承诺。赛事信息：https://gaac.gosim.org/')}`;const out=document.querySelector('#brief-output');out.className='form-result';out.innerHTML=`<strong>${t('Your brief is ready.','共建提议已生成。')}</strong><textarea readonly aria-label="${t('Your collaboration brief','你的共建提议')}"></textarea><button class="button small" data-action="download-brief">${t('Download brief','下载提议')} ↓</button> <button class="button small ghost" data-action="copy-brief">${t('Copy','复制')}</button>`;out.querySelector('textarea').value=brief;out.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'});}
  document.addEventListener('click',e=>{
    const target=e.target.closest('[data-action]');if(!target)return;
    const action=target.dataset.action;
    if(action==='theme'){theme=target.dataset.theme;setState();}
    if(action==='language'){lang=lang==='en'?'zh':'en';setState();}
    if(action==='menu'){const nav=document.querySelector('#main-nav');const open=nav.classList.toggle('is-open');target.setAttribute('aria-expanded',String(open));target.setAttribute('aria-label',open?t('Close navigation','关闭导航'):t('Open navigation','打开导航'));target.textContent=open?'×':'☰';}
    if(action==='print')window.print();
    if(action==='role'){document.querySelector('#role').value=target.dataset.role;document.querySelector('#contribution').focus();}
    if(action==='copy-prompt')copy(prompts[Number(target.dataset.prompt)]);
    if(action==='download-brief')download(brief,'GAAC-collaboration-brief.txt');
    if(action==='copy-brief')copy(brief);
  });
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelectorAll('.nav-dropdown[open]').forEach(d=>d.open=false);document.querySelector('#main-nav')?.classList.remove('is-open');const b=document.querySelector('.mobile-toggle');if(b){b.setAttribute('aria-expanded','false');b.textContent='☰';}}});
  addEventListener('popstate',()=>{const p=new URLSearchParams(location.search);theme=themes.includes(p.get('design'))?p.get('design'):'iris';lang=['en','zh'].includes(p.get('lang'))?p.get('lang'):'zh';typeface=typefaces.includes(p.get('type'))?p.get('type'):'michroma';cnFont=cnFonts.includes(p.get('cn'))?p.get('cn'):'chill';render();});
  render();
})();
